    ecp_sm2p256_sqr(tmp0, P->Z);
    ecp_sm2p256_mul(tmp1, tmp0, P->Z);
    ecp_sm2p256_mul(tmp0, tmp0, Q->X);
    ecp_sm2p256_mul(tmp1, tmp1, Q->Y);
    ecp_sm2p256_mul(sum.Y, P->Y, Q->Z);
    ecp_sm2p256_mul(sum.Z, Q->Z, P->Z);
